begin;
insert into public.cefr_builtin_bank(seed_key,payload)
select item->>'seedKey',item-'seedKey' from (select $cefr_mock${"title":"Multilevel Mock 10 · Public transport","description":"Original mashq varianti: public transport. 35 Listening, 35 Reading, 3 Writing va 8 Speaking topshirig‘i. Rasmiy test savollari emas.","level":"B1–C1","format":"multilevel","rightsConfirmed":true,"seedKey":"sinfquiz-multilevel-10","sections":[{"skill":"listening","minutes":45,"parts":[{"id":"listening-p1","title":"Short announcements","text":"Listen to eight short messages. Choose the best answer for each.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-10-part-1.mp3","imageUrl":"","questions":[{"id":"m10-l1-1","type":"choice","text":"When does the meeting begin?","options":["18:15","17:30","12:00"],"answers":["18:15"],"explanation":"The announcement says: The first message said 17:30, but the public transport meeting now starts at 18:15."},{"id":"m10-l1-2","type":"choice","text":"Where will people meet?","options":["the town hall","the railway café","Central Station"],"answers":["Central Station"],"explanation":"The announcement says: We are meeting at Central Station. Please do not wait at the old entrance."},{"id":"m10-l1-3","type":"choice","text":"What should visitors bring?","options":["a camera","a travel card","a printed ticket"],"answers":["a travel card"],"explanation":"The announcement says: Before you leave home, remember to bring a travel card. Other equipment is provided."},{"id":"m10-l1-4","type":"choice","text":"What is the last day to register?","options":["Monday","the following weekend","the day after the event"],"answers":["Monday"],"explanation":"The announcement says: You can sign up until Monday. We cannot add names at the door."},{"id":"m10-l1-5","type":"choice","text":"How much is admission?","options":["five pounds","ten pounds","free"],"answers":["free"],"explanation":"The announcement says: Admission is free. The amount covers the materials, and there is no extra charge."},{"id":"m10-l1-6","type":"choice","text":"Who can answer questions?","options":["the driver","Jamal","the caretaker"],"answers":["Jamal"],"explanation":"The announcement says: If you have a question, ask for Jamal at the information desk."},{"id":"m10-l1-7","type":"choice","text":"What did the team decide to do?","options":["adjust the bus departure by ten minutes","cancel the entire project","ignore the difficulty"],"answers":["adjust the bus departure by ten minutes"],"explanation":"The announcement says: Because the last bus left before some trains arrived, the team decided to adjust the bus departure by ten minutes."},{"id":"m10-l1-8","type":"choice","text":"What is the main purpose?","options":["to sell more tickets","to replace every volunteer","making evening journeys more reliable"],"answers":["making evening journeys more reliable"],"explanation":"The announcement says: We are doing this to support making evening journeys more reliable, not simply to advertise the event."}]},{"id":"listening-p2","title":"Briefing notes","text":"Listen to the briefing. Complete the notes with one word or number.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-10-part-2.mp3","imageUrl":"","questions":[{"id":"m10-l2-1","type":"text","text":"Which day is the briefing held? Write ONE word or number.","options":[],"answers":["Tuesday"],"explanation":"The briefing explicitly gives Tuesday."},{"id":"m10-l2-2","type":"text","text":"What time does the briefing start? Write ONE word or number.","options":[],"answers":["18:15"],"explanation":"The briefing explicitly gives 18:15."},{"id":"m10-l2-3","type":"text","text":"Who leads the first session? Write ONE word or number.","options":[],"answers":["Jamal"],"explanation":"The briefing explicitly gives Jamal."},{"id":"m10-l2-4","type":"text","text":"What is the registration deadline? Write ONE word or number.","options":[],"answers":["Monday"],"explanation":"The briefing explicitly gives Monday."},{"id":"m10-l2-5","type":"text","text":"How many entries were recorded? Write ONE word or number.","options":[],"answers":["20"],"explanation":"The briefing explicitly gives 20."},{"id":"m10-l2-6","type":"text","text":"Which word describes the main concern? Write ONE word or number.","options":[],"answers":["timing"],"explanation":"The briefing explicitly gives timing."}]},{"id":"listening-p3","title":"Four speakers","text":"Match four speakers with the main ideas. Two options are extra.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-10-part-3.mp3","imageUrl":"","questions":[{"id":"m10-l3-1","type":"choice","text":"Match speaker 1 with the main idea.","options":["Finding a sponsor","Rejecting the whole project","Personal motivation","Learning from a setback","Cautious optimism about a result","Planning the next stage"],"answers":["Personal motivation"],"explanation":"Speaker 1 focuses on personal motivation."},{"id":"m10-l3-2","type":"choice","text":"Match speaker 2 with the main idea.","options":["Rejecting the whole project","Personal motivation","Learning from a setback","Cautious optimism about a result","Planning the next stage","Finding a sponsor"],"answers":["Learning from a setback"],"explanation":"Speaker 2 focuses on learning from a setback."},{"id":"m10-l3-3","type":"choice","text":"Match speaker 3 with the main idea.","options":["Personal motivation","Learning from a setback","Cautious optimism about a result","Planning the next stage","Finding a sponsor","Rejecting the whole project"],"answers":["Cautious optimism about a result"],"explanation":"Speaker 3 focuses on cautious optimism about a result."},{"id":"m10-l3-4","type":"choice","text":"Match speaker 4 with the main idea.","options":["Learning from a setback","Cautious optimism about a result","Planning the next stage","Finding a sponsor","Rejecting the whole project","Personal motivation"],"answers":["Planning the next stage"],"explanation":"Speaker 4 focuses on planning the next stage."}]},{"id":"listening-p4","title":"Responding to requests","text":"Match each request to the response. Three options are extra.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-10-part-4.mp3","imageUrl":"","questions":[{"id":"m10-l4-1","type":"choice","text":"Which response was given to a visitor who cannot reach the upper floor?","options":["Help plan a follow-up session","Explain the sample limitation","Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule"],"answers":["Move activities to an accessible room"],"explanation":"The announcement connects this request with “move activities to an accessible room”."},{"id":"m10-l4-2","type":"choice","text":"Which response was given to a volunteer who needs to know the arrival time?","options":["Explain the sample limitation","Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session"],"answers":["Check the revised schedule"],"explanation":"The announcement connects this request with “check the revised schedule”."},{"id":"m10-l4-3","type":"choice","text":"Which response was given to someone who wants the project to continue?","options":["Read the equipment list","Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation"],"answers":["Help plan a follow-up session"],"explanation":"The announcement connects this request with “help plan a follow-up session”."},{"id":"m10-l4-4","type":"choice","text":"Which response was given to a researcher questioning the findings?","options":["Buy a new ticket immediately","Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation","Read the equipment list"],"answers":["Explain the sample limitation"],"explanation":"The announcement connects this request with “explain the sample limitation”."},{"id":"m10-l4-5","type":"choice","text":"Which response was given to a participant with an item to bring?","options":["Send the report to a newspaper","Replace all volunteers","Move activities to an accessible room","Check the revised schedule","Help plan a follow-up session","Explain the sample limitation","Read the equipment list","Buy a new ticket immediately"],"answers":["Read the equipment list"],"explanation":"The announcement connects this request with “read the equipment list”."}]},{"id":"listening-p5","title":"Three conversations","text":"Listen to three conversations. Answer two questions about each.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-10-part-5.mp3","imageUrl":"","questions":[{"id":"m10-l5-1","type":"choice","text":"Why is the speaker cautious?","options":["There was no trial.","The report was lost.","holiday traffic was not included"],"answers":["holiday traffic was not included"],"explanation":"Conversation 1 states this clearly."},{"id":"m10-l5-2","type":"choice","text":"What does the speaker recommend?","options":["buying a larger room","another trial","closing the project"],"answers":["another trial"],"explanation":"Conversation 1 states this clearly."},{"id":"m10-l5-3","type":"choice","text":"Which option does the second speaker prefer?","options":["neither option","coordinated schedules","more advertising signs"],"answers":["coordinated schedules"],"explanation":"Conversation 2 states this clearly."},{"id":"m10-l5-4","type":"choice","text":"Why does the speaker prefer it?","options":["making evening journeys more reliable","it is the oldest option","it needs no volunteers"],"answers":["making evening journeys more reliable"],"explanation":"Conversation 2 states this clearly."},{"id":"m10-l5-5","type":"choice","text":"Who will speak?","options":["Jamal","the driver","the caretaker"],"answers":["Jamal"],"explanation":"Conversation 3 states this clearly."},{"id":"m10-l5-6","type":"choice","text":"Why did the plan change?","options":["a lack of interest","a change in the weather forecast","the last bus left before some trains arrived"],"answers":["the last bus left before some trains arrived"],"explanation":"Conversation 3 states this clearly."}]},{"id":"listening-p6","title":"Project lecture","text":"Listen to the lecture and write one word or number for each answer.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"/cefr-audio/mock-10-part-6.mp3","imageUrl":"","questions":[{"id":"m10-l6-1","type":"text","text":"What do the collected records form? Write ONE word or number.","options":[],"answers":["evidence"],"explanation":"The lecture uses the word evidence."},{"id":"m10-l6-2","type":"text","text":"What is the total highlighted in the report? Write ONE word or number.","options":[],"answers":["20"],"explanation":"The lecture uses the word 20."},{"id":"m10-l6-3","type":"text","text":"Which word describes the key idea? Write ONE word or number.","options":[],"answers":["timing"],"explanation":"The lecture uses the word timing."},{"id":"m10-l6-4","type":"text","text":"What did the team ask visitors for? Write ONE word or number.","options":[],"answers":["feedback"],"explanation":"The lecture uses the word feedback."},{"id":"m10-l6-5","type":"text","text":"What must be understood behind a result? Write ONE word or number.","options":[],"answers":["conditions"],"explanation":"The lecture uses the word conditions."},{"id":"m10-l6-6","type":"text","text":"Which section contains the final interpretation? Write ONE word or number.","options":[],"answers":["conclusions"],"explanation":"The lecture uses the word conclusions."}]}]},{"skill":"reading","minutes":60,"parts":[{"id":"reading-p1","title":"One-word gaps","text":"The public transport project depended on (1) ____ who gave their time freely. At first, the team followed a fixed (2) ____, but the last bus left before some trains arrived. Careful (3) ____ showed exactly when the difficulty appeared. The organisers asked visitors for (4) ____ before changing the plan. They also wanted better (5) ____ for people who could not use the first arrangement. In the end, the strongest (6) ____ came from connection counts on twenty weekdays. None of these observations proves that the same approach would work in every town. Nevertheless, the group learned why small, well-recorded changes can matter. Its next meeting will consider whether review the timetable after three months is practical and who could help.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m10-r1-1","type":"text","text":"Complete gap 1 with ONE word.","options":[],"answers":["volunteers"],"explanation":"“volunteers” makes the sentence grammatically and logically complete."},{"id":"m10-r1-2","type":"text","text":"Complete gap 2 with ONE word.","options":[],"answers":["schedule"],"explanation":"“schedule” makes the sentence grammatically and logically complete."},{"id":"m10-r1-3","type":"text","text":"Complete gap 3 with ONE word.","options":[],"answers":["records"],"explanation":"“records” makes the sentence grammatically and logically complete."},{"id":"m10-r1-4","type":"text","text":"Complete gap 4 with ONE word.","options":[],"answers":["feedback"],"explanation":"“feedback” makes the sentence grammatically and logically complete."},{"id":"m10-r1-5","type":"text","text":"Complete gap 5 with ONE word.","options":[],"answers":["access"],"explanation":"“access” makes the sentence grammatically and logically complete."},{"id":"m10-r1-6","type":"text","text":"Complete gap 6 with ONE word.","options":[],"answers":["evidence"],"explanation":"“evidence” makes the sentence grammatically and logically complete."}]},{"id":"reading-p2","title":"Notices and needs","text":"A. Guided introduction: meet Jamal at Central Station on Tuesday.\nB. Quiet hour: a smaller group meets before the main session.\nC. Access help: ask about step-free rooms and larger-print information.\nD. Skills desk: volunteers demonstrate practical methods and tools.\nE. Family visit: activities are planned for adults and children together.\nF. Research corner: examine the report and ask how information was collected.\nG. Follow-up team: help organise review the timetable after three months.\nH. Short briefing: Jamal gives a twenty-minute overview.\nI. Merchandise desk: souvenirs are available after the event.\nJ. Private room hire: businesses can book an unrelated meeting.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m10-r2-1","type":"choice","text":"Which notice suits this person? A visitor wants a guided introduction.","options":["A","B","C","D","E","F","G","H","I","J"],"answers":["A"],"explanation":"Notice A offers exactly this service."},{"id":"m10-r2-2","type":"choice","text":"Which notice suits this person? Someone prefers a smaller, quieter group.","options":["B","C","D","E","F","G","H","I","J","A"],"answers":["B"],"explanation":"Notice B offers exactly this service."},{"id":"m10-r2-3","type":"choice","text":"Which notice suits this person? A person needs access information.","options":["C","D","E","F","G","H","I","J","A","B"],"answers":["C"],"explanation":"Notice C offers exactly this service."},{"id":"m10-r2-4","type":"choice","text":"Which notice suits this person? A learner wants a hands-on demonstration.","options":["D","E","F","G","H","I","J","A","B","C"],"answers":["D"],"explanation":"Notice D offers exactly this service."},{"id":"m10-r2-5","type":"choice","text":"Which notice suits this person? A parent wants to bring a child.","options":["E","F","G","H","I","J","A","B","C","D"],"answers":["E"],"explanation":"Notice E offers exactly this service."},{"id":"m10-r2-6","type":"choice","text":"Which notice suits this person? A visitor wants to inspect the evidence.","options":["F","G","H","I","J","A","B","C","D","E"],"answers":["F"],"explanation":"Notice F offers exactly this service."},{"id":"m10-r2-7","type":"choice","text":"Which notice suits this person? A resident wants to help with the next event.","options":["G","H","I","J","A","B","C","D","E","F"],"answers":["G"],"explanation":"Notice G offers exactly this service."},{"id":"m10-r2-8","type":"choice","text":"Which notice suits this person? Someone has only twenty minutes available.","options":["H","I","J","A","B","C","D","E","F","G"],"answers":["H"],"explanation":"Notice H offers exactly this service."}]},{"id":"reading-p3","title":"Paragraph headings","text":"Headings: A. The original difficulty | B. A practical adjustment | C. Collecting information | D. What the figures show | E. A reason for caution | F. The next question | G. A celebrity endorsement | H. An unrelated invention\n\nA. The idea behind public transport began with making evening journeys more reliable. People welcomed the aim, but the first arrangement was less reliable than the team expected. In particular, the last bus left before some trains arrived. Several participants described this as a problem of planning rather than a reason to abandon the work. Their observations were recorded instead of being dismissed.\n\nB. The organisers compared a complicated solution with a manageable one. They chose to adjust the bus departure by ten minutes. This did not remove every difficulty, yet it made the next session possible without asking volunteers to start again. Jamal then explained the revised procedure to participants, including those who had missed the first announcement.\n\nC. Good intentions alone could not tell the team whether the change helped. They gathered connection counts on twenty weekdays and kept notes about the conditions under which each observation was made. When a record was incomplete, they marked it as uncertain rather than filling in a likely answer. This made the report less dramatic but more useful.\n\nD. According to the team, missed connections fell during a four-week trial. The figure attracted attention because it described an observable outcome, not merely a prediction. It also encouraged more residents to ask how they could take part. However, a number by itself says little about the people or circumstances behind it.\n\nE. The report acknowledges that holiday traffic was not included. A different location, season or group of participants might produce a different result. The team therefore resisted a claim that its method was universally successful. This careful interpretation helped readers separate the evidence from the organisers' hopes.\n\nF. The final recommendation was to review the timetable after three months. Before doing so, the organisers want to agree on clear measures of success and an accessible way to collect comments. They also plan to compare coordinated schedules with more advertising signs rather than assuming one choice will be best for every participant.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m10-r3-1","type":"choice","text":"Choose a heading for paragraph A.","options":["Collecting information","What the figures show","A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment"],"answers":["The original difficulty"],"explanation":"Paragraph A develops the idea “the original difficulty”."},{"id":"m10-r3-2","type":"choice","text":"Choose a heading for paragraph B.","options":["What the figures show","A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information"],"answers":["A practical adjustment"],"explanation":"Paragraph B develops the idea “a practical adjustment”."},{"id":"m10-r3-3","type":"choice","text":"Choose a heading for paragraph C.","options":["A reason for caution","The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show"],"answers":["Collecting information"],"explanation":"Paragraph C develops the idea “collecting information”."},{"id":"m10-r3-4","type":"choice","text":"Choose a heading for paragraph D.","options":["The next question","A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution"],"answers":["What the figures show"],"explanation":"Paragraph D develops the idea “what the figures show”."},{"id":"m10-r3-5","type":"choice","text":"Choose a heading for paragraph E.","options":["A celebrity endorsement","An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution","The next question"],"answers":["A reason for caution"],"explanation":"Paragraph E develops the idea “a reason for caution”."},{"id":"m10-r3-6","type":"choice","text":"Choose a heading for paragraph F.","options":["An unrelated invention","The original difficulty","A practical adjustment","Collecting information","What the figures show","A reason for caution","The next question","A celebrity endorsement"],"answers":["The next question"],"explanation":"Paragraph F develops the idea “the next question”."}]},{"id":"reading-p4","title":"Detailed article","text":"An invitation to take part in public transport appeared at Central Station. Its stated aim was making evening journeys more reliable. The first public meeting was held on Tuesday, and Jamal collected the comments. Early reports suggested enthusiasm, but the team also heard practical concerns. Most notably, the last bus left before some trains arrived. It would have been easy to present this as a minor inconvenience. Instead, the organisers documented it and chose to adjust the bus departure by ten minutes.\n\nThe revised activity did not follow exactly the original schedule. The organisers tested the change, recorded connection counts on twenty weekdays, and compared comments made before and after the adjustment. Their report states that missed connections fell during a four-week trial. The authors are careful to explain the difference between an observation and a prediction: a positive first month does not guarantee a positive first year.\n\nTwo alternatives were discussed. Some participants supported coordinated schedules; others preferred more advertising signs. Neither option was dismissed without consideration. The report ultimately recommended a limited further trial rather than an immediate permanent decision. Its main reservation was that holiday traffic was not included. Jamal said that the next stage would be to review the timetable after three months.\n\nThe report does not give the ages of the visitors, the exact amount of any future grant, or a date for publishing a second edition. Those details may matter later, but a reader should not invent them now. The value of the project lies partly in its willingness to say what remains unknown.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m10-r4-1","type":"choice","text":"What was the stated aim of the project?","options":["to replace public transport","to close the venue","making evening journeys more reliable","to sell souvenirs"],"answers":["making evening journeys more reliable"],"explanation":"The opening paragraph states the aim."},{"id":"m10-r4-2","type":"choice","text":"What led the organisers to revise the activity?","options":["a competition prize","the last bus left before some trains arrived","a new mayor","a cancelled newspaper"],"answers":["the last bus left before some trains arrived"],"explanation":"The reported problem led directly to the adjustment."},{"id":"m10-r4-3","type":"choice","text":"Which action did the organisers take?","options":["adjust the bus departure by ten minutes","stop collecting comments","claim guaranteed success","ignore accessibility"],"answers":["adjust the bus departure by ten minutes"],"explanation":"The revised action is explicitly described."},{"id":"m10-r4-4","type":"choice","text":"How do the authors treat the positive early result?","options":["As proof for every community","As an error to hide","As irrelevant to the project","As useful but limited evidence"],"answers":["As useful but limited evidence"],"explanation":"The text distinguishes observation from prediction."},{"id":"m10-r4-5","type":"choice","text":"True / False / Not Given: The team recorded information during the revised activity.","options":["False","Not Given","True"],"answers":["True"],"explanation":"The second paragraph says the team recorded evidence."},{"id":"m10-r4-6","type":"choice","text":"True / False / Not Given: The organisers permanently rejected both alternatives.","options":["Not Given","True","False"],"answers":["False"],"explanation":"Both alternatives were considered; a further trial was recommended."},{"id":"m10-r4-7","type":"choice","text":"True / False / Not Given: Every visitor was younger than eighteen.","options":["True","False","Not Given"],"answers":["Not Given"],"explanation":"No ages are supplied."},{"id":"m10-r4-8","type":"choice","text":"True / False / Not Given: The report identifies a limitation of the trial.","options":["False","Not Given","True"],"answers":["True"],"explanation":"The report acknowledges a limitation."},{"id":"m10-r4-9","type":"choice","text":"True / False / Not Given: A second edition will be published next month.","options":["Not Given","True","False"],"answers":["Not Given"],"explanation":"No date for a second edition is given."}]},{"id":"reading-p5","title":"Analysis and inference","text":"The organisers at Central Station made a useful distinction between a change that is easy to announce and a change that can be evaluated. Their focus was making evening journeys more reliable. During the first stage, the last bus left before some trains arrived. The immediate response was to adjust the bus departure by ten minutes, but the team did not describe this response as a complete solution.\n\nTo check what happened, they collected connection counts on twenty weekdays. The report highlighted a figure of 20. A short account of the trial was sent to Jamal, who asked for more information about the conditions in which it took place. In particular, holiday traffic was not included. This mattered because an impressive number from a narrow trial can be misleading when removed from its context.\n\nAt the next meeting, participants will compare coordinated schedules with more advertising signs. They will also consider how to review the timetable after three months. The discussion is designed to invite disagreement supported by reasons, not to reward the loudest speaker. If the group can repeat the trial and explain its limitations clearly, the result will be more useful to other communities.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m10-r5-1","type":"text","text":"Which venue hosted the organisers? Write ONE word from the venue name.","options":[],"answers":["Central"],"explanation":"The venue starts with Central."},{"id":"m10-r5-2","type":"text","text":"What figure did the report highlight? Write ONE number.","options":[],"answers":["20"],"explanation":"The figure given is 20."},{"id":"m10-r5-3","type":"text","text":"Who requested more information? Write ONE name.","options":[],"answers":["Jamal"],"explanation":"The text names Jamal."},{"id":"m10-r5-4","type":"text","text":"What can be misleading without context? Write ONE word.","options":[],"answers":["number"],"explanation":"The passage describes an impressive number from a narrow trial."},{"id":"m10-r5-5","type":"choice","text":"Why does the writer mention the limitation?","options":["To avoid hearing from participants","To hide the report","To prevent an overconfident conclusion","To argue that evidence is useless"],"answers":["To prevent an overconfident conclusion"],"explanation":"The writer warns against removing the result from context."},{"id":"m10-r5-6","type":"choice","text":"What attitude does the final paragraph encourage?","options":["Competition for attention","Reasoned disagreement","Silence at meetings","Immediate approval of every idea"],"answers":["Reasoned disagreement"],"explanation":"The group invites disagreement supported by reasons."}]}]},{"skill":"writing","minutes":60,"parts":[{"id":"writing-p1","title":"Tasks 1.1, 1.2 and 2","text":"Write all three responses. Your work is assessed by an administrator.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m10-w1","type":"writing","text":"You and a friend attended an activity about public transport. Write an informal message to your friend. Explain what you enjoyed and suggest one thing to do next. Aim for about 50 words.","options":[],"answers":[],"explanation":""},{"id":"m10-w2","type":"writing","text":"Write to Jamal, the organiser at Central Station. Explain why you attended, describe the difficulty (“the last bus left before some trains arrived”), and suggest a practical improvement. Use a suitable formal tone. Aim for about 120–150 words.","options":[],"answers":[],"explanation":""},{"id":"m10-w3","type":"writing","text":"Some people think communities should invest in coordinated schedules; others prefer more advertising signs. Discuss both views and explain which approach would better support making evening journeys more reliable. Give reasons and examples. Aim for about 180–220 words.","options":[],"answers":[],"explanation":""}]}]},{"skill":"speaking","minutes":15,"parts":[{"id":"speaking-p1","title":"Part 1.1 — personal questions","text":"Record one answer per prompt.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m10-s1-1","type":"speaking","text":"What do you enjoy doing in your neighbourhood?","options":[],"answers":[],"explanation":""},{"id":"m10-s1-2","type":"speaking","text":"How do you usually learn about local events?","options":[],"answers":[],"explanation":""},{"id":"m10-s1-3","type":"speaking","text":"Have you ever visited a place like Central Station?","options":[],"answers":[],"explanation":""}]},{"id":"speaking-p2","title":"Part 1.2 — compare two scenes","text":"Scene A: a small group working together. Scene B: a large public presentation. Compare the two situations.","source":"SinfQuiz original mashq materiali, 2026. Format uchun: uzbmb.uz/page/test_sinovlari_formati","audioUrl":"","imageUrl":"","questions":[{"id":"m10-s2-1","type":"speaking","text":"Compare a small group discussion at Central Station with a large public meeting. What might each be like?","options":[],"answers":[],"explanation":""},{"id":"m10-s2-2","type":"speaking","text":"Which setting would help people discuss public transport more effectively, and why?","options":[],"answers":[],"explanation":""},{"id":"m10-s2-3","type":"speak